command:
// ============================================================
// LUNAS WIRKUNG: WEISSER SPEER (ZERZAL)
//
// - Ahne: Zerzal
// - Ein selbst gewählter Speer aus dem Inventar
// - Keine GM-Anfrage, direkte Effektanlage auf dem eigenen Akteur über Block 6
// - Schaden gegen Geister/Untote verdoppelt & TP erhöht um +[QS/3]
// - Wirkungskarte über Block 11
// - Ein vorhandener Weißer-Speer-Effekt wird automatisch ersetzt
// ============================================================

(async function () {

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden ||
        !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);

        if (!fwMacro) {
            return ui.notifications.error(
                "Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!"
            );
        }

        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden ||
        !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen
    ) {
        return ui.notifications.error(
            "Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!"
        );
    }

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Weißer Speer";
    const ahne = "Zerzal";
    const suchbegriff = "Speer";
    const basisEffektName = `${gabenName} (${ahne})`;

    const basisBeschreibung =
        `Die Macht Zerzals dringt in den Speer ein. Der Schaden gegen materialisierte Geister und Untote wird verdoppelt. ` +
        `Die TP erhöhen sich um <b>+{TP_BONUS}</b> <span style="font-size: 0.85em; font-weight: normal;">({QS}QS/3)</span>. ` +
        `Wirkt das Zerzalkind die Gabe auf einen zweiten Speer, verliert der erste seine Wirkung.`;

    const dauerText = "Bis zur nächsten Vollmondnacht";
    const abschlussText =
        "Der Speer verliert seinen übernatürlichen Zustand und wird wieder zu einem ganz normalen Speer. Zerzals Macht ruht.";

    DSK_FW.EffektEnde.Register(
        "weisserspeerzerzal",
        basisEffektName,
        abschlussText
    );

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenQS");
        }
    };

    const findeAlteSpeerEffekte = actor =>
        (actor?.effects || []).filter(effect => {
            const name = effect.name || effect.label || "";
            const istPassenderName =
                name === basisEffektName ||
                name.startsWith(`${basisEffektName} -`);

            const istUnserEffekt =
                effect.getFlag("dsk", "weisserspeer") === true ||
                effect.getFlag("dsk", "ahnenId") === "weisserspeerzerzal";

            return istPassenderName && istUnserEffekt;
        });

    const loescheEffekt = async effect => {
        if (!effect) return false;

        try {
            await effect.delete();
            return true;
        } catch (error) {
            console.error(
                "Weißer Speer: Alter Effekt konnte nicht entfernt werden.",
                error
            );
            return false;
        }
    };

    const berechneTpBonus = qs =>
        Math.max(1, Math.floor(Number(qs) / 3));

    // +++ 4 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    let casterActor =
        canvas.tokens.controlled[0]?.actor ||
        game.user.character ||
        null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables
                .map(token => token.actor)
                .find(actor =>
                    actor?.getFlag(
                        "world",
                        "letzteGabenQS"
                    ) !== undefined
                ) ||

            game.actors.find(actor =>
                actor.getFlag(
                    "world",
                    "letzteGabenQS"
                ) !== undefined
            ) ||

            null;
    }

    if (!casterActor) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle zuerst deinen Token aus, liebes Zerzalkind!"
        );
    }

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterName =
        DSK_FW.ResolveTokenName(casterActor);

    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,

        suchbegriffe: [
            "Weißer Speer Probe",
            "Weißer Speer"
        ],

        testDataObj:
            typeof testData !== "undefined"
                ? testData
                : null,

        fallback: 0,
        protokollieren: true
    });

    if (qs <= 0) {
        await raeumeQSAuf(casterActor);

        return ui.notifications.warn(
            "Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!"
        );
    }

    const tpBonus = berechneTpBonus(qs);
    const beschreibung = basisBeschreibung
        .replace("{TP_BONUS}", String(tpBonus))
        .replace("{QS}", String(qs));

    // +++ 5 - SPEER AUS DEM INVENTAR WÄHLEN +++++++++++++++++++

    let zuDurchsuchendeItems = [];
    if (casterActor.itemTypes) {
        if (casterActor.itemTypes["meleeweapon"]) zuDurchsuchendeItems.push(...casterActor.itemTypes["meleeweapon"]);
        if (casterActor.itemTypes["rangeweapon"]) zuDurchsuchendeItems.push(...casterActor.itemTypes["rangeweapon"]);
        if (casterActor.itemTypes["weapon"]) zuDurchsuchendeItems.push(...casterActor.itemTypes["weapon"]);
    }
    if (zuDurchsuchendeItems.length === 0) {
        zuDurchsuchendeItems = casterActor.items.filter(i => 
            i.type === "meleeweapon" || 
            i.type === "rangeweapon" || 
            i.type === "weapon" || 
            (i.type && i.type.includes("weapon"))
        );
    }

    const gefundeneItems = zuDurchsuchendeItems.filter(item =>
        (item.name || "")
            .toLowerCase()
            .includes(suchbegriff.toLowerCase())
    );

    if (!gefundeneItems.length) {
        await raeumeQSAuf(casterActor);

        return ui.notifications.warn(
            `Luna sagt 🌙: Kein passender Gegenstand (${suchbegriff}) im Inventar gefunden!`
        );
    }

    const optionen =
        gefundeneItems.map(item =>
            `<option value="${item.uuid}">${foundry.utils.escapeHTML(item.name)}</option>`
        ).join("");

    // +++ 6 - AUSWAHLDIALOG +++++++++++++++++++++++++++++++++++

    const dialogResult =
        await foundry.applications.api.DialogV2.wait({
            window: {
                title: gabenName
            },

            position: {
                width: 420
            },

            content: `
                <form>
                    <div style="font-family:'Signika',sans-serif;">
                        ${DSK_FW.UI.Header(
                            basisEffektName,
                            DSK_FW.Symbol(ahne)
                        )}

                        <div class="dskbox2" style="margin-top:10px;">
                            <p style="font-size:.95em;line-height:1.35;">
                                ${beschreibung}
                            </p>

                            <div style="margin-top:10px;">
                                <label style="font-weight:bold;font-size:.9em;">
                                    Wähle deinen Speer:
                                </label>

                                <select name="gegenstandUuid"
                                    style="width:100%;padding:4px;margin-top:4px;font-family:'Signika',sans-serif;">
                                    ${optionen}
                                </select>
                            </div>

                            <hr style="margin:10px 0;">

                            <p style="text-align:center;font-weight:bold;">
                                Wirkungsdauer: ${dauerText}
                            </p>
                        </div>
                    </div>
                </form>
            `,

            rejectClose: false,

            buttons: [
                {
                    action: "anwenden",
                    label: "Gabe wirken",
                    icon: "fas fa-magic",
                    default: true,

                    callback: event => {
                        const form =
                            event.target.closest("form");

                        return form
                            ? new FormData(form).get("gegenstandUuid")
                            : null;
                    }
                },
                {
                    action: "abbrechen",
                    label: "Abbrechen",
                    icon: "fas fa-times",
                    callback: () => false
                }
            ]
        });

    if (!dialogResult || dialogResult === false) {
        await raeumeQSAuf(casterActor);
        return;
    }

    const item = await fromUuid(dialogResult);

    if (
        !item ||
        item.parent?.uuid !== casterActor.uuid
    ) {
        await raeumeQSAuf(casterActor);

        return ui.notifications.warn(
            "Luna sagt 🌙: Der ausgewählte Speer konnte nicht mehr gefunden werden!"
        );
    }

    // +++ 7 - ALTEN EIGENEN EFFEKT ERSETZEN +++++++++++++++++++

    const alteEffekte =
        findeAlteSpeerEffekte(casterActor);

    for (const effect of alteEffekte) {
        const geloescht =
            await loescheEffekt(effect);

        if (!geloescht) {
            await raeumeQSAuf(casterActor);

            return ui.notifications.error(
                "Luna sagt 🌙: Der bisherige Speer-Effekt konnte nicht entfernt werden!"
            );
        }
    }

    // +++ 8 - EFFEKT DIREKT ÜBER BLOCK 6 ++++++++++++++++++++++

    const finalerEffektName =
        `${basisEffektName} - ${item.name}`;

    const wirkungText =
        `Der Speer <b>${item.name}</b> ist von Zerzals Macht erfüllt. ` +
        `Der Schaden gegen materialisierte Geister und Untote ist verdoppelt, die TP sind um <b>+${tpBonus}</b> erhöht.` +
        `<br><br><b>Wirkungsdauer:</b> ${dauerText}` +
        `<br><b>Gabe gewirkt von:</b> ${casterName}`;

    const changes = [
        { key: "system.meleeStats.damage", mode: 2, value: tpBonus, priority: 20 },
        { key: "system.rangeStats.damage", mode: 2, value: tpBonus, priority: 20 },
        { key: "system.creatureBonus",      mode: 0, value: "Geist *2",  priority: 20 },
        { key: "system.creatureBonus",      mode: 0, value: "Untote *2", priority: 20 }
    ];

    const neuerEffekt =
        await DSK_FW.Effekt.Anwenden({
            name: finalerEffektName,
            ahne,
            beschreibung: wirkungText,
            gabeZiel: "",
            qs,
            ziel: casterActor,

            changes: changes,
            origin: casterActor.uuid,
            showIcon: 1,

            flags: {
                dsk: {
                    weisserspeer: true,
                    ahnenId: "weisserspeerzerzal",
                    casterUuid: casterActor.uuid,
                    casterName,
                    itemUuid: item.uuid,
                    itemName: item.name,
                    tpBonus,
                    qs
                }
            }
        });

    if (!neuerEffekt) {
        await raeumeQSAuf(casterActor);

        return ui.notifications.error(
            "Luna sagt 🌙: Zerzals Segen konnte nicht auf den Speer übertragen werden!"
        );
    }

    // +++ 9 - WIRKUNGSKARTE ÜBER BLOCK 11 ++++++++++++++++++++

    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: basisEffektName,
        ahne,
        beschreibung,
        wirkender: casterName,

        ziele: [{
            name: item.name,
            rolle: "Geweihter Speer"
        }],

        misserfolge: [],
        dauerText,

        gmBereich: false,
        angewendet: true,
        erfolgreich: true,
        anfragenderUserId: game.user.id
    });

    // +++ 10 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);

    ui.notifications.info(
        `Luna sagt 🌙: ${item.name} wurde von Zerzal gesegnet.`
    );

}).call(this);
